command -v python3>/dev/null||exit 127;python3 -c 'import sys,math as m,json as j;P=(2,3,5,7,11,13);N=int(sys.argv[1])if len(sys.argv)>1 else 4;K=128;E=lambda a:m.prod(p**(x+1)for p,x in zip(P,a));D=lambda g:[(lambda p:(lambda f:f(f,g,0))(lambda f,n,k:f(f,n//p,k+1)if n%p==0 else k))(p)-1 for p in P];Z=lambda s:sum((1 if k%2 else -1)*k**(-s)for k in range(1,K+1))/(1-2**(1-s));a=[0,0,1,0,1,1];R=[];exec("for n in range(N):\n g=E(a);b=D(g);x=sum((v+1)*m.log(p)for p,v in zip(P,a));s=.5+1j*(x%40);y=Z(s);q=(int(abs(y.real)*1000)%3,int(abs(y.imag)*1000)%3);R.append([n,g,a[:],round(x,6),[round(y.real,6),round(y.imag,6)],q]);a=[(a[0]+1+q[0])%4,(a[1]+a[5])%7,(a[2]+q[1])%3,a[3],a[4],-a[5]]");print(j.dumps({"model":"PRIME_FACTOR_GODEL_TM","state":"G=prod(p^(a+1))","exact":all(D(E(r[2]))==r[2]for r in R),"X":"log(G)=sum((a+1)log p)","Y":"zeta(X) via finite eta approximation","levels":R,"omega":"formal colim","omega_attained":0,"program_equals_zeta":0,"open":1,"final":0},separators=(",",":")))' "$@"